WorkbenchTaskPaginationQuery:
query WorkbenchTaskPaginationQuery(
  $count: Int = 20
  $cursor: String
  $id: ID!
) {
  node(id: $id) {
    __typename
    ...WorkbenchTask_task_1G22uz
    id
  }
}

fragment WorkbenchTask_task_1G22uz on TurnTask {
  id
  status
  latestSequence
  persistence
  latestFrame {
    id
    phase
    kind
    answer
    error
    sequence
  }
  result {
    id
    answer
    error
    httpStatus
    episodeId
  }
  frames(first: $count, after: $cursor) {
    edges {
      node {
        id
        sequence
        kind
        phase
        __typename
      }
      cursor
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
}

WorkbenchTaskQuery:
query WorkbenchTaskQuery(
  $id: ID!
) {
  turnTask(id: $id) {
    ...WorkbenchTask_task
    id
  }
}

fragment WorkbenchTask_task on TurnTask {
  id
  status
  latestSequence
  persistence
  latestFrame {
    id
    phase
    kind
    answer
    error
    sequence
  }
  result {
    id
    answer
    error
    httpStatus
    episodeId
  }
  frames(first: 20) {
    edges {
      node {
        id
        sequence
        kind
        phase
        __typename
      }
      cursor
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
}

WorkbenchTaskSubscription:
subscription WorkbenchTaskSubscription(
  $id: ID!
  $afterSequence: Int!
) {
  turnTaskUpdated(id: $id, afterSequence: $afterSequence) {
    id
    status
    latestSequence
    persistence
    latestFrame {
      id
      phase
      kind
      answer
      error
      sequence
    }
    result {
      id
      answer
      error
      httpStatus
      episodeId
    }
  }
}
